package com.growworld.controller;
import com.growworld.dto.*; import com.growworld.dto.ActivityDtos.*; import com.growworld.dto.DashboardDtos.*; import com.growworld.service.ProgressService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.UUID; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*;
@Validated @RestController @RequestMapping("/api/v1") public class ActivityController {private final ProgressService service;public ActivityController(ProgressService s){service=s;} @GetMapping("/dashboard") Dashboard dashboard(Authentication a){return service.dashboard(id(a));} @PostMapping("/activities") @ResponseStatus(HttpStatus.CREATED) CreatedActivity create(Authentication a,@Valid @RequestBody CreateRequest r){return service.create(id(a),r);} @GetMapping("/activities") PageResponse history(Authentication a,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return service.history(id(a),page,size);} private UUID id(Authentication a){return (UUID)a.getPrincipal();}}
